def __post_init__(self):
    if self.price < 0:
        raise ValueError("price cannot be negative")
    if self.stock < 0:
        raise ValueError("stock cannot be negative")
    if not self.active and self.stock > 0:
        self.active = True
    if self.sku is None:
        self.sku = str(uuid.uuid4())
